function LadderStruggleFormationDialog:OnNormalFightClick()
    local isCanBattle, errStr = self:IsCanBattle()
    if not isCanBattle then
        GameUtils.Toast(errStr)
        return
    end

    cs_coroutine.start(function()
        local succeed = false
        local operation = GameUtils.Request(self.component.InterfaceAt, {atPlayerId = self.playerInfoList[2].playerId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            succeed = true
            local jsonData = response.data
            local recordData = jsonData.battleData
            local statistics = jsonData.statistics
            LadderStruggleMgr = import('Game.UI.UIBattling.LadderStruggle.LadderStruggleMgr')
            LadderStruggleMgr:Init()
            LadderStruggleMgr:SetSystem(self.systemName)
            LadderStruggleMgr:SetPlayerInfoList(self.playerInfoList)
            LadderStruggleMgr:SetLadderStruggleData(recordData, statistics)
            LadderStruggleMgr:Preprocessing()
            local json = LadderStruggleMgr:GetLadderStruggleNextSessionData()
            LadderStruggleMgr:FightReplay(json)
            -- 刷新我的排名
            self.component:OnMyRankRefresh(checkInt(jsonData.myPlayerRanking))
        end)

        while not succeed do
            cs_coroutine.yield_return()
        end
    end)
end

function LadderStruggleFormationDialog:OnQuickFightClick()
    local isCanBattle, errStr = self:IsCanBattle()
    if not isCanBattle then
        GameUtils.Toast(errStr)
        return
    end

    cs_coroutine.start(function()
        local succeed = false
        local operation = GameUtils.Request(self.component.InterfaceAt, {atPlayerId = self.playerInfoList[2].playerId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            succeed = true
            local jsonData = response.data
            local recordData = jsonData.battleData
            local statistics = jsonData.statistics
            LadderStruggleMgr = import('Game.UI.UIBattling.LadderStruggle.LadderStruggleMgr')
            LadderStruggleMgr:Init()
            LadderStruggleMgr:SetSystem(self.systemName)
            LadderStruggleMgr:SetPlayerInfoList(self.playerInfoList)
            LadderStruggleMgr:SetLadderStruggleData(recordData, statistics)
            LadderStruggleMgr:Preprocessing()
            cs_coroutine.start(function()
                cs_coroutine.yield_return(UIModule.OpenDialog({ id = self.component.UIBattleAbstractDialog, parameters = {directShowBattleEnd = false, systemName = self.systemName}}))
                -- 快速战斗不会重新打开home页，不会刷新门票，所以这里再客户端自己算一下
                self.component:AddTicketCount(-1)
                self.component:StartTimeDown()
                -- 刷新home页上的每日胜利宝箱状态
                local dialog = UIModule.CurrentScreen:GetDialog(self.component.UIMainDialog)
                if isNotNull(dialog) then
                    local boxState = checkInt(jsonData.isDrawBox) + 1
                    local isWin = LadderStruggleMgr.scoreL > LadderStruggleMgr.scoreR
                    local lt = dialog.Env
                    lt.LB_DailyReward.Env:AddBattleNum(isWin and 1 or 0)
                    lt.LB_DailyReward.Env:SetButtonState(boxState)
                end
                -- 刷新我的排名
                self.component:OnMyRankRefresh(checkInt(jsonData.myPlayerRanking))
                UIModule.CloseDialog(self.controller)
            end)
        end)
    end)
end

