--是否可以战斗
function LadderStruggleFormationDialog:IsCanBattle()
    local ticketNum = GoodsUtils.GetThingNo(self.component.ticketId)
    if ticketNum <= 0 then
        return false, localize('幻影训练证不足')
    end

    local teamCount = 1
    if self.component.questId == Constants.SpecialQuestId.LadderStruggleId then
        teamCount = 3
    elseif self.component.questId == Constants.SpecialQuestId.LadderStruggleSingleId then
        teamCount = 1
    end

    local isHaveMember = true
    for i = 1, teamCount do
        local t = self.teamComponent:GetTeamByQuestId(self.component.questId, i)
        local count = self.teamComponent:GetTeamMemberCount(t) 
        if count <= 0 then
            isHaveMember = false
            break
        end
    end
    if not isHaveMember then
        return false, localize("每个队伍都不能为空")
    end

    return true
end

return LadderStruggleFormationDialog


